// Extract request data
const topic = $json.body.topic;
const audience = $json.body.audience || 'millennial';
const slideCount = $json.body.slideCount || 7;
const tone = $json.body.tone || 'casual';

// Build prompt untuk Custom GPT/Gemini
const prompt = `Buatkan konten carousel Instagram tentang "${topic}" untuk target audience ${audience}, ${slideCount} slide, tone ${tone}.\n\nOutput dalam format PHP array sesuai knowledge base.`;

// Knowledge base reference
const knowledgeBaseUrl = 'https://custom-ai-two.vercel.app/api/knowledge/all';
const githubUrl = 'https://github.com/lumakaraid/custom-ai/tree/main/knowledge-base';

return {
  json: {
    prompt,
    topic,
    audience,
    slideCount,
    tone,
    knowledgeBaseUrl,
    githubUrl,
    instructions: 'Copy prompt ini dan paste ke Custom GPT atau Gemini Gem untuk generate content',
    note: 'n8n hanya sebagai gateway, tidak perlu OpenAI API key'
  }
};
